76	  public static Path createPath(PointF startPoint, PointF endPoint, PointF cp1, PointF cp2) {
77	    Path path = new Path();
78	    path.moveTo(startPoint.x, startPoint.y);
79	
80	    if (cp1 != null && cp2 != null && (cp1.length() != 0 || cp2.length() != 0)) {
81	      path.cubicTo(
82	          startPoint.x + cp1.x, startPoint.y + cp1.y,
83	          endPoint.x + cp2.x, endPoint.y + cp2.y,
84	          endPoint.x, endPoint.y);
85	    } else {
86	      path.lineTo(endPoint.x, endPoint.y);
87	    }
88	    return path;
89	  }
