91	  public static void closeQuietly(Closeable closeable) {
92	    if (closeable != null) {
93	      try {
94	        closeable.close();
95	      } catch (RuntimeException rethrown) {
96	        throw rethrown;
97	      } catch (Exception ignored) {
98	        // Ignore.
99	      }
100	    }
101	  }
