103	  public static float getScale(Matrix matrix) {
104	    final float[] points = threadLocalPoints.get();
105	
106	    points[0] = 0;
107	    points[1] = 0;
108	    // Use 1/sqrt(2) so that the hypotenuse is of length 1.
109	    points[2] = INV_SQRT_2;
110	    points[3] = INV_SQRT_2;
111	    matrix.mapPoints(points);
112	    float dx = points[2] - points[0];
113	    float dy = points[3] - points[1];
114	
115	    return (float) Math.hypot(dx, dy);
116	  }
