118	  public static boolean hasZeroScaleAxis(Matrix matrix) {
119	    final float[] points = threadLocalPoints.get();
120	
121	    points[0] = 0;
122	    points[1] = 0;
123	    // Random numbers. The only way these should map to the same thing as 0,0 is if the scale is 0.
124	    points[2] = 37394.729378f;
125	    points[3] = 39575.2343807f;
126	    matrix.mapPoints(points);
127	    return points[0] == points[2] || points[1] == points[3];
128	  }
