231	      minPatch) {
232	    if (major < minMajor) {
233	      return false;
234	    } else if (major > minMajor) {
235	      return true;
236	    }
237	
238	    if (minor < minMinor) {
239	      return false;
240	    } else if (minor > minMinor) {
241	      return true;
242	    }
243	
244	    return patch >= minPatch;
