280	   * Resize the bitmap to exactly the same size as the specified dimension, changing the aspect ratio if needed.
281	   * Returns the original bitmap if the dimensions already match.
282	   */
283	  public static Bitmap resizeBitmapIfNeeded(@NonNull Bitmap bitmap, int width, int height) {
284	    if (bitmap.getWidth() == width && bitmap.getHeight() == height) {
285	      return bitmap;
286	    }
287	    Bitmap resizedBitmap = Bitmap.createScaledBitmap(bitmap, width, height, true);
288	    bitmap.recycle();
289	    return resizedBitmap;
