3	/**
4	 * Use this instead of {@link android.animation.ArgbEvaluator} because it interpolates through the gamma color
5	 * space which looks better to us humans.
6	 * <p>
7	 * Written by Romain Guy and Francois Blavoet.
8	 * https://androidstudygroup.slack.com/archives/animation/p1476461064000335
9	 */
10	public class GammaEvaluator {
11	
12	  // Opto-electronic conversion function for the sRGB color space
13	  // Takes a gamma-encoded sRGB value and converts it to a linear sRGB value
14	  private static float OECF_sRGB(float linear) {
15	    // IEC 61966-2-1:1999
16	    return linear <= 0.0031308f ?
17	        linear * 12.92f : (float) ((Math.pow(linear, 1.0f / 2.4f) * 1.055f) - 0.055f);
18	  }
19	
20	  // Electro-optical conversion function for the sRGB color space
21	  // Takes a linear sRGB value and converts it to a gamma-encoded sRGB value
22	  private static float EOCF_sRGB(float srgb) {
23	    // IEC 61966-2-1:1999
24	    return srgb <= 0.04045f ? srgb / 12.92f : (float) Math.pow((srgb + 0.055f) / 1.055f, 2.4f);
25	  }
26	
27	  public static int evaluate(float fraction, int startInt, int endInt) {
28	    // Fast return in case start and end is the same
29	    // or if fraction is at start/end or out of [0,1] bounds
30	    if (startInt == endInt) {
31	      return startInt;
32	    } else if (fraction <= 0f) {
33	      return startInt;
34	    } else if (fraction >= 1f) {
35	      return endInt;
36	    }
37	
38	    float startA = ((startInt >> 24) & 0xff) / 255.0f;
39	    float startR = ((startInt >> 16) & 0xff) / 255.0f;
40	    float startG = ((startInt >> 8) & 0xff) / 255.0f;
41	    float startB = (startInt & 0xff) / 255.0f;
42	
43	    float endA = ((endInt >> 24) & 0xff) / 255.0f;
44	    float endR = ((endInt >> 16) & 0xff) / 255.0f;
45	    float endG = ((endInt >> 8) & 0xff) / 255.0f;
46	    float endB = (endInt & 0xff) / 255.0f;
47	
48	    // convert from sRGB to linear
49	    startR = EOCF_sRGB(startR);
50	    startG = EOCF_sRGB(startG);
51	    startB = EOCF_sRGB(startB);
52	
53	    endR = EOCF_sRGB(endR);
54	    endG = EOCF_sRGB(endG);
55	    endB = EOCF_sRGB(endB);
56	
57	    // compute the interpolated color in linear space
58	    float a = startA + fraction * (endA - startA);
59	    float r = startR + fraction * (endR - startR);
60	    float g = startG + fraction * (endG - startG);
61	    float b = startB + fraction * (endB - startB);
62	
63	    // convert back to sRGB in the [0..255] range
64	    a = a * 255.0f;
65	    r = OECF_sRGB(r) * 255.0f;
66	    g = OECF_sRGB(g) * 255.0f;
67	    b = OECF_sRGB(b) * 255.0f;
68	
69	    return Math.round(a) << 24 | Math.round(r) << 16 | Math.round(g) << 8 | Math.round(b);
70	  }
71	}
