10	import java.io.IOException;
11	import java.util.ArrayList;
12	import java.util.List;
13	
14	class JsonUtils {
15	  private JsonUtils() {
16	  }
17	
18	  /**
19	   * [r,g,b]
20	   */
21	  @ColorInt static int jsonToColor(JsonReader reader) throws IOException {
22	    reader.beginArray();
23	    int r = (int) (reader.nextDouble() * 255);
24	    int g = (int) (reader.nextDouble() * 255);
25	    int b = (int) (reader.nextDouble() * 255);
26	    while (reader.hasNext()) {
27	      reader.skipValue();
28	    }
29	    reader.endArray();
30	    return Color.argb(255, r, g, b);
31	  }
32	
33	  static List<PointF> jsonToPoints(JsonReader reader, float scale) throws IOException {
34	    List<PointF> points = new ArrayList<>();
35	
36	    reader.beginArray();
37	    while (reader.peek() == JsonReader.Token.BEGIN_ARRAY) {
38	      reader.beginArray();
39	      points.add(jsonToPoint(reader, scale));
40	      reader.endArray();
41	    }
42	    reader.endArray();
43	    return points;
44	  }
45	
46	  static PointF jsonToPoint(JsonReader reader, float scale) throws IOException {
47	    switch (reader.peek()) {
48	      case NUMBER:
49	        return jsonNumbersToPoint(reader, scale);
50	      case BEGIN_ARRAY:
51	        return jsonArrayToPoint(reader, scale);
52	      case BEGIN_OBJECT:
53	        return jsonObjectToPoint(reader, scale);
54	      default:
55	        throw new IllegalArgumentException("Unknown point starts with " + reader.peek());
56	    }
57	  }
58	
59	  private static PointF jsonNumbersToPoint(JsonReader reader, float scale) throws IOException {
60	    float x = (float) reader.nextDouble();
61	    float y = (float) reader.nextDouble();
62	    while (reader.hasNext()) {
63	      reader.skipValue();
64	    }
65	    return new PointF(x * scale, y * scale);
66	  }
67	
68	  private static PointF jsonArrayToPoint(JsonReader reader, float scale) throws IOException {
69	    float x;
70	    float y;
71	    reader.beginArray();
72	    x = (float) reader.nextDouble();
73	    y = (float) reader.nextDouble();
74	    while (reader.peek() != JsonReader.Token.END_ARRAY) {
75	      reader.skipValue();
76	    }
77	    reader.endArray();
78	    return new PointF(x * scale, y * scale);
79	  }
80	
81	  private static final JsonReader.Options POINT_NAMES = JsonReader.Options.of("x", "y");
82	
83	  private static PointF jsonObjectToPoint(JsonReader reader, float scale) throws IOException {
84	    float x = 0f;
85	    float y = 0f;
86	    reader.beginObject();
87	    while (reader.hasNext()) {
88	      switch (reader.selectName(POINT_NAMES)) {
89	        case 0:
90	          x = valueFromObject(reader);
91	          break;
92	        case 1:
93	          y = valueFromObject(reader);
94	          break;
95	        default:
96	          reader.skipName();
97	          reader.skipValue();
98	      }
99	    }
100	    reader.endObject();
101	    return new PointF(x * scale, y * scale);
102	  }
103	
104	  static float valueFromObject(JsonReader reader) throws IOException {
105	    JsonReader.Token token = reader.peek();
106	    switch (token) {
107	      case NUMBER:
108	        return (float) reader.nextDouble();
109	      case BEGIN_ARRAY:
110	        reader.beginArray();
111	        float val = (float) reader.nextDouble();
112	        while (reader.hasNext()) {
113	          reader.skipValue();
114	        }
115	        reader.endArray();
116	        return val;
117	      default:
118	        throw new IllegalArgumentException("Unknown value for token of type " + token);
119	    }
120	  }
121	}
