19	  /**
20	   * Optimization to avoid autoboxing.
21	   */
22	  int getIntValue(Keyframe<Integer> keyframe, float keyframeProgress) {
23	    if (keyframe.startValue == null) {
24	      throw new IllegalStateException("Missing values for keyframe.");
