23	/**
24	 * An OffscreenLayer encapsulates a "child surface" onto which canvas draw calls can be issued.
25	 * At the end, the result of these draw calls will be composited onto the parent surface, with
26	 * user-provided alpha, blend mode, color filter, and drop shadow.
27	 * <p>
28	 * To use the OffscreenLayer, call its start() method with the necessary parameters, draw
29	 * to the returned canvas, and then call finish() to composite the result onto the main canvas.
30	 * <p>
31	 * In this sense, using an OffscreenLayer is very similar to the Canvas.saveLayer() family
32	 * of functions, and in fact forwards to Canvas.saveLayer() when appropriate.
33	 * <p>
34	 * Unlike Canvas.saveLayer(), an OffscreenLayer also supports compositing with a drop-shadow,
35	 * and uses a hardware-accelerated target when available. It attempts to choose the fastest
36	 * approach to render and composite the contents, up to and including simply rendering
37	 * directly, if possible.
38	 */
39	public class OffscreenLayer {
40	  /**
41	   * Encapsulates configuration for compositing the layer contents on the parent. Similar to
42	   * Paint, but only includes operations that the OffscreenLayer can support.
43	   */
44	  public static class ComposeOp {
45	    public int alpha;
46	    @Nullable public BlendModeCompat blendMode;
47	    @Nullable public ColorFilter colorFilter;
48	    @Nullable public DropShadow shadow;
49	
50	    public ComposeOp() {
51	      reset();
52	    }
53	
54	    public boolean isTranslucent() {
55	      return alpha < 255;
56	    }
57	
58	    public boolean hasBlendMode() {
59	      return blendMode != null && blendMode != BlendModeCompat.SRC_OVER;
60	    }
61	
62	    public boolean hasShadow() {
63	      return shadow != null;
64	    }
65	
66	    public boolean hasColorFilter() {
67	      return colorFilter != null;
68	    }
69	
70	    public boolean isNoop() {
71	      return !isTranslucent() && !hasBlendMode() && !hasShadow() && !hasColorFilter();
72	    }
73	
74	    public void reset() {
75	      alpha = 255;
76	      blendMode = null;
77	      colorFilter = null;
78	      shadow = null;
79	    }
80	  }
81	
82	  protected enum RenderStrategy {
83	      /** No-op: simply render to the underlying canvas directly. */
84	      DIRECT,
85	      /** Use Canvas.saveLayer() and compose using Canvas.restore(). */
86	      SAVE_LAYER,
87	      /** Render everything onto an off-screen bitmap and then draw it onto the main canvas */
88	      BITMAP,
89	      /** Render into a RenderNode's display-list and then draw the render node. (Hardware accelerated) */
90	      RENDER_NODE
91	  }
92	
93	  /** Parent render surface should compose onto. null if no rendering is in progress. */
94	  @Nullable private Canvas parentCanvas;
95	  /** Configuration for compositing the layer onto parentCanvas */
96	  @Nullable private ComposeOp op;
97	  /** Strategy that we've chosen for rendering this pass */
98	  private RenderStrategy currentStrategy;
99	  /** Rectangle that the final composition will occupy in the screen */
100	  @Nullable private RectF targetRect;
101	  /** targetRect with shadow render space included */
102	  @Nullable private RectF rectIncludingShadow;
103	  @Nullable private Rect intRectIncludingShadow;
104	  @Nullable private RectF tmpRect;
105	  @Nullable private RectF scaledRectIncludingShadow;
106	  @Nullable private Rect shadowBitmapSrcRect;
107	
108	  @Nullable private RectF scaledBounds;
109	
110	  private final static Matrix IDENTITY_MATRIX = new Matrix();
111	
112	  // For RenderStrategy.SAVE_LAYER:
113	  /** Paint passed to Utils.saveLayerCompat(). */
114	  @Nullable private Paint composePaint;
115	
116	  // For RenderStrategy.BITMAP:
117	  @Nullable private Bitmap bitmap;
118	  @Nullable private Canvas bitmapCanvas;
119	  @Nullable private Rect bitmapSrcRect;
120	  @Nullable private LPaint clearPaint;
121	
122	  /** Temporary variable to store the parent canvas Matrix */
123	  @Nullable Matrix parentCanvasMatrix;
124	  /** parentCanvas' pre-existing matrix when start() was called */
125	  @Nullable float[] preExistingTransform;
126	
127	  // Android doesn't render shadows on arbitrary bitmaps correctly. Instead, if we're using
128	  // render-to-bitmap, we have to draw them manually. To do so, we need an additional bitmap, an
129	  // associated canvas, paint, and some other data, which we define as members to avoid
130	  // reallocation. (And also because in the render-node case, we won't need them.)
131	  @Nullable private Bitmap shadowBitmap;
132	  @Nullable private Bitmap shadowMaskBitmap;
133	  @Nullable private Canvas shadowBitmapCanvas;
134	  @Nullable private Canvas shadowMaskBitmapCanvas;
135	  @Nullable private LPaint shadowPaint;
136	  @Nullable private BlurMaskFilter shadowBlurFilter;
137	  private float lastShadowBlurRadius = 0.0f;
138	
139	  // For RenderStrategy.RENDER_NODE:
140	  @Nullable private RenderNode renderNode; // Render node with the initial contents of the layer
141	  @Nullable private RenderNode shadowRenderNode; // Render node for the shadow
142	  @Nullable private DropShadow lastRenderNodeShadow;
143	
144	  public OffscreenLayer() {
145	  }
146	
147	  private RenderStrategy chooseRenderStrategy(Canvas parentCanvas, ComposeOp op) {
148	    if (op.isNoop()) {
149	      // Can draw directly onto the final canvas, results will look the same.
150	      return RenderStrategy.DIRECT;
151	    }
152	
153	    if (!op.hasShadow()) {
154	      // Canvas.saveLayer() supports alpha-compositing, blend modes, and color filters, which is
155	      // sufficient for this case, and is faster than manually maintaining an off-screen bitmap.
156	      // It is not clear if it's faster than RENDER_NODE and when, but this is what we've been
157	      // doing prior to OffscreenLayer, so keep that behavior to be safe and avoid regressions.
158	      return RenderStrategy.SAVE_LAYER;
159	    }
160	
161	    // Beyond this point, we are sure that we need to render a drop shadow.
162	
163	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q || !parentCanvas.isHardwareAccelerated()) {
164	      // We don't have support for the RenderNode API, or we're rendering to a software canvas
165	      // which doesn't support RenderNodes anyhow. This is the slowest path: render to a bitmap,
166	      // add a shadow manually on CPU.
167	      return RenderStrategy.BITMAP;
168	    }
169	
170	    if (Build.VERSION.SDK_INT <= Build.VERSION_CODES.S) {
171	      // RenderEffect, which we need for shadows, was only introduced in S. This means that, pre-S,
172	      // we have to do renderShadow() on a bitmap, like in the BITMAP case. However, since it's not
173	      // possible to draw a RenderNode to a software-rendering canvas, there would be no way to get
174	      // our RenderNode contents onto a bitmap where we can renderShadow(). Therefore, fall back to
175	      // full bitmap mode.
176	      return RenderStrategy.BITMAP;
177	    }
178	
179	    // The RenderNode and RenderEffect APIs are available, so use hardware acceleration.
180	    return RenderStrategy.RENDER_NODE;
181	  }
