290	        composePaint.setAlpha(op.alpha);
291	
292	        childCanvas = bitmapCanvas;
293	        childCanvas.scale(pixelScaleX, pixelScaleY); // Replicate scaling applied by parentCanvas
294	        childCanvas.translate(-bounds.left, -bounds.top); // So that the image begins at the top-left of the bitmap
295	        break;
296	
297	      case RENDER_NODE:
298	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
299	          throw new IllegalStateException("RenderNode not supported but we chose it as render strategy");
300	        }
301	
302	        if (renderNode == null) renderNode = new RenderNode("OffscreenLayer.main");
303	        if (op.hasShadow() && shadowRenderNode == null) {
304	          shadowRenderNode = new RenderNode("OffscreenLayer.shadow");
305	          lastRenderNodeShadow = null;
306	        }
307	
308	        // The render node needs some data in advance
309	        if (op.hasBlendMode() || op.hasColorFilter()) {
310	          composePaint.reset();
311	          PaintCompat.setBlendMode(composePaint, op.blendMode);
312	          composePaint.setColorFilter(op.colorFilter);
313	          renderNode.setUseCompositingLayer(true, composePaint);
314	
315	          if (op.hasShadow()) {
316	            if (shadowRenderNode == null) {
317	              throw new IllegalStateException("Must initialize shadowRenderNode when we have shadow");
318	            }
319	            shadowRenderNode.setUseCompositingLayer(true, composePaint);
320	          }
321	        }
322	        renderNode.setAlpha(op.alpha / 255.f);
323	        if (op.hasShadow()) {
324	          if (shadowRenderNode == null) {
325	            throw new IllegalStateException("Must initialize shadowRenderNode when we have shadow");
326	          }
327	
328	          // lottie-web composes the shadow onto the canvas first, and then the
329	          // contents separately - mirror this behavior
330	          shadowRenderNode.setAlpha(op.alpha / 255.f);
331	        }
332	        renderNode.setHasOverlappingRendering(true);
333	        renderNode.setPosition((int)scaledBounds.left, (int)scaledBounds.top, (int)scaledBounds.right, (int)scaledBounds.bottom);
334	
335	        childCanvas = renderNode.beginRecording((int) scaledBounds.width(), (int) scaledBounds.height());
336	        childCanvas.setMatrix(OffscreenLayer.IDENTITY_MATRIX);
337	        childCanvas.scale(pixelScaleX, pixelScaleY); // Replicate scaling applied by parentCanvas
338	        childCanvas.translate(-bounds.left, -bounds.top); // So that the image begins at the top-left of the bitmap
339	        break;
340	
341	      default:
342	        throw new RuntimeException("Invalid render strategy for OffscreenLayer");
343	    }
344	
345	    return childCanvas;
346	  }
347	
348	  public void finish() {
349	    if (parentCanvas == null || op == null || preExistingTransform == null || targetRect == null) {
350	      throw new IllegalStateException("OffscreenBitmap: finish() call without matching start()");
351	    }
352	
353	    switch (currentStrategy) {
354	      case DIRECT:
355	      case SAVE_LAYER:
356	        parentCanvas.restore();
357	        break;
358	
359	      case BITMAP:
360	        if (bitmap == null) {
361	          throw new IllegalStateException("Bitmap is not ready; should've been initialized at start() time");
362	        }
363	
364	        if (op.hasShadow()) {
365	          // Composing the shadow first and then the content like this will be incorrect in the
366	          // presence of op.blendMode. However, that is not used at the moment, so this
367	          // optimization is safe. (Otherwise, we'd have to have another bitmap here for the
368	          // intermediate result.)
369	          renderBitmapShadow(parentCanvas, op.shadow);
370	        }
371	
372	        if (bitmapSrcRect == null) bitmapSrcRect = new Rect();
373	        bitmapSrcRect.set(0, 0, (int)(targetRect.width() * preExistingTransform[Matrix.MSCALE_X]), (int)(targetRect.height() * preExistingTransform[Matrix.MSCALE_Y]));
374	        parentCanvas.drawBitmap(bitmap, bitmapSrcRect, targetRect, composePaint);
375	        break;
376	
377	      case RENDER_NODE:
378	        if (renderNode == null) {
379	          throw new IllegalStateException("RenderNode is not ready; should've been initialized at start() time");
380	        }
381	
382	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
383	          throw new IllegalStateException("RenderNode not supported but we chose it as render strategy");
384	        }
385	
386	        parentCanvas.save();
387	        parentCanvas.scale(1.0f / preExistingTransform[Matrix.MSCALE_X], 1.0f / preExistingTransform[Matrix.MSCALE_Y]);
388	        renderNode.endRecording();
389	        if (op.hasShadow()) {
390	          // Composing the shadow first and then the content like this will be incorrect in the
391	          // presence of op.blendMode. However, that is not used at the moment, so this
392	          // optimization is safe. (Otherwise, we'd have to have another render node here for the
393	          // intermediate result.)
394	          renderHardwareShadow(parentCanvas, op.shadow);
395	        }
396	        parentCanvas.drawRenderNode(renderNode);
397	        parentCanvas.restore();
398	        break;
399	    }
400	
401	    parentCanvas = null;
402	  }
403	
404	  private RectF calculateRectIncludingShadow(RectF rect, DropShadow shadow) {
405	    if (rectIncludingShadow == null) rectIncludingShadow = new RectF();
406	    if (tmpRect == null) tmpRect = new RectF();
407	    rectIncludingShadow.set(rect);
408	    rectIncludingShadow.offsetTo(rect.left + shadow.getDx(), rect.top + shadow.getDy());
409	    rectIncludingShadow.inset(-shadow.getRadius(), -shadow.getRadius());
410	    tmpRect.set(rect);
411	    rectIncludingShadow.union(tmpRect);
412	    return rectIncludingShadow;
413	  }
414	
415	  /** Renders a shadow (only the shadow) of this.bitmap to the provided canvas. */
416	  private void renderBitmapShadow(Canvas targetCanvas, DropShadow shadow) {
417	    if (targetRect == null || bitmap == null) {
418	      throw new IllegalStateException("Cannot render to bitmap outside a start()/finish() block");
419	    }
420	
421	    // This is an expanded rect that encompasses the full extent of the shadow.
422	    RectF rectIncludingShadow = calculateRectIncludingShadow(targetRect, shadow);
423	    if (intRectIncludingShadow == null) intRectIncludingShadow = new Rect();
424	    intRectIncludingShadow.set(
425	        (int)Math.floor(rectIncludingShadow.left),
426	        (int)Math.floor(rectIncludingShadow.top),
427	        (int)Math.ceil(rectIncludingShadow.right),
428	        (int)Math.ceil(rectIncludingShadow.bottom)
429	    );
430	    float pixelScaleX = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_X] : 1.0f;
431	    float pixelScaleY = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_Y] : 1.0f;
432	    if (scaledRectIncludingShadow == null) scaledRectIncludingShadow = new RectF();
433	    scaledRectIncludingShadow.set(
434	        rectIncludingShadow.left * pixelScaleX,
435	        rectIncludingShadow.top * pixelScaleY,
436	        rectIncludingShadow.right * pixelScaleX,
437	        rectIncludingShadow.bottom * pixelScaleY
438	    );
439	
440	    if (shadowBitmapSrcRect == null) shadowBitmapSrcRect = new Rect();
441	    shadowBitmapSrcRect.set(0, 0, (int)Math.round(scaledRectIncludingShadow.width()), (int)Math.round(scaledRectIncludingShadow.height()));
442	    if (needNewBitmap(shadowBitmap, scaledRectIncludingShadow)) {
443	      if (shadowBitmap != null) {
444	        deallocateBitmap(shadowBitmap);
445	      }
446	      if (shadowMaskBitmap != null) {
447	        deallocateBitmap(shadowMaskBitmap);
448	      }
449	
450	      shadowBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ARGB_8888);
451	      shadowMaskBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ALPHA_8);
452	      shadowBitmapCanvas = new Canvas(shadowBitmap);
453	      shadowMaskBitmapCanvas = new Canvas(shadowMaskBitmap);
454	    } else {
455	      if (shadowBitmapCanvas == null || shadowMaskBitmapCanvas == null || clearPaint == null) {
456	        throw new IllegalStateException("If needNewBitmap() returns true, we should have a canvas and bitmap ready");
457	      }
458	      shadowBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
459	      shadowMaskBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
460	    }
461	
462	    if (shadowMaskBitmap == null) throw new IllegalStateException("Expected to have allocated a shadow mask bitmap");
463	    
464	    if (shadowPaint == null) {
465	      shadowPaint = new LPaint(Paint.ANTI_ALIAS_FLAG);
466	    }
467	
468	    // This is the offset of targetRect inside rectIncludingShadow
469	    float offsetX = targetRect.left - rectIncludingShadow.left;
470	    float offsetY = targetRect.top - rectIncludingShadow.top;
471	
472	    // Draw the image onto the mask layer first. Since the mask layer is ALPHA_8, this discards color information.
473	    // Align it so that when drawn in the end, it originates at targetRect.x, targetRect.y
474	    // the int casts are very important here - they save us from some slow path for non-integer coords
475	    shadowMaskBitmapCanvas.drawBitmap(bitmap, (int)Math.round(offsetX * pixelScaleX), (int)Math.round(offsetY * pixelScaleY), null);
476	
477	    // Prepare the shadow paint. This is the paint that will perform a blur and a tint of the mask
478	    if (shadowBlurFilter == null || lastShadowBlurRadius != shadow.getRadius()) {
479	      float scaledRadius = shadow.getRadius() * (pixelScaleX + pixelScaleY) / 2.0f;
480	      if (scaledRadius > 0) {
481	        shadowBlurFilter = new BlurMaskFilter(scaledRadius, BlurMaskFilter.Blur.NORMAL);
482	      } else {
483	        shadowBlurFilter = null;
484	      }
485	
486	      lastShadowBlurRadius = shadow.getRadius();
487	    }
488	    shadowPaint.setColor(shadow.getColor());
489	    if (shadow.getRadius() > 0.0f) {
490	      shadowPaint.setMaskFilter(shadowBlurFilter);
491	    } else {
492	      shadowPaint.setMaskFilter(null);
493	    }
494	    shadowPaint.setFilterBitmap(true);
495	
496	    // Draw the mask onto our shadowBitmap with the shadowPaint. This bitmap now contains the final
497	    // look of the shadow, correctly positioned inside a rectIncludingShadow-sized area
498	    // the int casts are very important here - they save us from some slow path for non-integer coords
499	    shadowBitmapCanvas.drawBitmap(shadowMaskBitmap, (int)Math.round(shadow.getDx() * pixelScaleX), (int)Math.round(shadow.getDy() * pixelScaleY), shadowPaint);
500	
501	    // Now blit the result onto the final canvas. It might be tempting to skip shadowBitmap and draw the mask
502	    // directly onto the canvas with shadowPaint, but this breaks the blur, since Paint.setMaskFilter() is not
503	    // supported on hardware canvases.
504	    targetCanvas.drawBitmap(shadowBitmap, shadowBitmapSrcRect, intRectIncludingShadow, composePaint);
505	  }
506	
507	  /** Renders a shadow (only the shadow) of this.renderNode to the provided canvas. */
508	  private void renderHardwareShadow(Canvas targetCanvas, DropShadow shadow) {
509	    if (renderNode == null || shadowRenderNode == null) {
510	      throw new IllegalStateException("Cannot render to render node outside a start()/finish() block");
511	    }
512	
513	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) {
514	      throw new RuntimeException("RenderEffect is not supported on API level <31");
515	    }
516	
517	    // The render node canvas is in the pre-pixelscale space, so we have to scale the shadow parameters
518	    // by the pixel scale
519	    float pixelScaleX = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_X] : 1.0f;
520	    float pixelScaleY = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_Y] : 1.0f;
521	
522	    if (lastRenderNodeShadow == null || !shadow.sameAs(lastRenderNodeShadow)) {
523	      RenderEffect effect = RenderEffect.createColorFilterEffect(new PorterDuffColorFilter(shadow.getColor(), PorterDuff.Mode.SRC_IN));
524	      if (shadow.getRadius() > 0.0f) {
525	        float scaledRadius = shadow.getRadius() * (pixelScaleX + pixelScaleY) / 2.0f;
526	        effect = RenderEffect.createBlurEffect(scaledRadius, scaledRadius, effect, Shader.TileMode.CLAMP);
527	      }
528	      shadowRenderNode.setRenderEffect(effect);
529	      lastRenderNodeShadow = shadow;
530	    }
531	
532	    RectF rectIncludingShadow = calculateRectIncludingShadow(targetRect, shadow);
533	    if (scaledRectIncludingShadow == null) scaledRectIncludingShadow = new RectF();
534	    scaledRectIncludingShadow.set(
535	        rectIncludingShadow.left * pixelScaleX,
536	        rectIncludingShadow.top * pixelScaleY,
537	        rectIncludingShadow.right * pixelScaleX,
538	        rectIncludingShadow.bottom * pixelScaleY
539	    );
540	
541	    shadowRenderNode.setPosition(0, 0, (int)scaledRectIncludingShadow.width(), (int)scaledRectIncludingShadow.height());
542	    Canvas shadowCanvas = shadowRenderNode.beginRecording((int)scaledRectIncludingShadow.width(), (int)scaledRectIncludingShadow.height());
543	    // Offset so that the image starts at the top left, and then offset by shadow displacement
544	    shadowCanvas.translate(-scaledRectIncludingShadow.left + shadow.getDx() * pixelScaleX, -scaledRectIncludingShadow.top + shadow.getDy() * pixelScaleY);
545	    shadowCanvas.drawRenderNode(renderNode);
546	    shadowRenderNode.endRecording();
547	
548	    targetCanvas.save();
549	    targetCanvas.translate(scaledRectIncludingShadow.left, scaledRectIncludingShadow.top);
550	    targetCanvas.drawRenderNode(shadowRenderNode);
551	    targetCanvas.restore();
552	  }
553	
554	  /**
555	   * Whether calling finish() will decrement the save count of the [Canvas] returned by [start()].
556	   */
557	  public boolean finishDecrementsCanvasSaveCount() {
558	    // endRecording() will decrement the save count of the Canvas returned by beginRecording()
559	    return currentStrategy == RenderStrategy.RENDER_NODE;
560	  }
561	}
