  private static boolean matchesMagicBytes(BufferedSource inputSource, byte[] magic) {
    try {
      BufferedSource peek = inputSource.peek();
      for (byte b : magic) {
        if (peek.readByte() != b) {
          return false;
        }
      }
      peek.close();
      return true;
    } catch (NoSuchMethodError e) {
      // This happens in the Android Studio layout preview.
