495	  private List<TextSubLine> splitGlyphTextIntoLines(String textLine, float boxWidth, Font font, float fontScale, float tracking,
496	      boolean usingGlyphs) {
497	    int lineCount = 0;
498	
499	    float currentLineWidth = 0;
500	    int currentLineStartIndex = 0;
501	
502	    int currentWordStartIndex = 0;
503	    float currentWordWidth = 0f;
504	    boolean nextCharacterStartsWord = false;
505	
506	    // The measured size of a space.
507	    float spaceWidth = 0f;
508	
509	    for (int i = 0; i < textLine.length(); i++) {
510	      char c = textLine.charAt(i);
511	      float currentCharWidth;
512	      if (usingGlyphs) {
513	        int characterHash = FontCharacter.hashFor(c, font.getFamily(), font.getStyle());
514	        FontCharacter character = composition.getCharacters().get(characterHash);
515	        if (character == null) {
516	          continue;
517	        }
518	        currentCharWidth = (float) character.getWidth() * fontScale * Utils.dpScale() + tracking;
519	      } else {
520	        currentCharWidth = fillPaint.measureText(textLine.substring(i, i + 1)) + tracking;
521	      }
522	
523	      if (c == ' ') {
524	        spaceWidth = currentCharWidth;
525	        nextCharacterStartsWord = true;
526	      } else if (nextCharacterStartsWord) {
527	        nextCharacterStartsWord = false;
528	        currentWordStartIndex = i;
529	        currentWordWidth = currentCharWidth;
530	      } else {
531	        currentWordWidth += currentCharWidth;
532	      }
533	      currentLineWidth += currentCharWidth;
534	
535	      if (boxWidth > 0f && currentLineWidth >= boxWidth) {
536	        if (c == ' ') {
537	          // Spaces at the end of a line don't do anything. Ignore it.
538	          // The next non-space character will hit the conditions below.
539	          continue;
540	        }
541	        TextSubLine subLine = ensureEnoughSubLines(++lineCount);
542	        if (currentWordStartIndex == currentLineStartIndex) {
543	          // Only word on line is wider than box, start wrapping mid-word.
544	          String substr = textLine.substring(currentLineStartIndex, i);
545	          String trimmed = substr.trim();
546	          float trimmedSpace = (trimmed.length() - substr.length()) * spaceWidth;
547	          subLine.set(trimmed, currentLineWidth - currentCharWidth - trimmedSpace);
548	          currentLineStartIndex = i;
549	          currentLineWidth = currentCharWidth;
550	          currentWordStartIndex = currentLineStartIndex;
551	          currentWordWidth = currentCharWidth;
552	        } else {
553	          String substr = textLine.substring(currentLineStartIndex, currentWordStartIndex - 1);
554	          String trimmed = substr.trim();
555	          float trimmedSpace = (substr.length() - trimmed.length()) * spaceWidth;
556	          subLine.set(trimmed, currentLineWidth - currentWordWidth - trimmedSpace - spaceWidth);
557	          currentLineStartIndex = currentWordStartIndex;
558	          currentLineWidth = currentWordWidth;
559	        }
560	      }
561	    }
562	    if (currentLineWidth > 0f) {
563	      TextSubLine line = ensureEnoughSubLines(++lineCount);
564	      line.set(textLine.substring(currentLineStartIndex), currentLineWidth);
565	    }
566	    return textSubLines.subList(0, lineCount);
567	  }
