570	   * Elements are reused and not deleted to save allocations.
571	   */
572	  private TextSubLine ensureEnoughSubLines(int numLines) {
573	    for (int i = textSubLines.size(); i < numLines; i++) {
574	      textSubLines.add(new TextSubLine());
575	    }
576	    return textSubLines.get(numLines - 1);
577	  }
