207	  /**
208	   * Ensures that setProgress and draw will never happen at the same time on different threads.
209	   * If that were to happen, parts of the animation may be on one frame while other parts would
210	   * be on another.
211	   */
212	  private final Semaphore setProgressDrawLock = new Semaphore(1);
213	  /**
214	   * The executor that {@link AsyncUpdates} will be run on.
215	   * <p/>
216	   * Defaults to a core size of 0 so that when no animations are playing, there will be no
217	   * idle cores consuming resources.
218	   * <p/>
219	   * Allows up to two active threads so that if there are many animations, they can all work in parallel.
220	   * Two was arbitrarily chosen but should be sufficient for most uses cases. In the case of a single
221	   * animation, this should never exceed one.
222	   * <p/>
223	   * Each thread will timeout after 35ms which gives it enough time to persist for one frame, one dropped frame
224	   * and a few extra ms just in case.
225	   */
226	  private static final Executor setProgressExecutor = new ThreadPoolExecutor(0, 2, 35, TimeUnit.MILLISECONDS,
227	      new LinkedBlockingQueue<>(), new LottieThreadFactory());
228	  private Handler mainThreadHandler;
229	  private Runnable invalidateSelfRunnable;
230	
231	  private final Runnable updateProgressRunnable = () -> {
232	    CompositionLayer compositionLayer = this.compositionLayer;
233	    if (compositionLayer == null) {
234	      return;
235	    }
236	    try {
237	      setProgressDrawLock.acquire();
238	      compositionLayer.setProgress(animator.getAnimatedValueAbsolute());
239	      // Refer to invalidateSelfOnMainThread for more info.
240	      if (invalidateSelfOnMainThread && isDirty) {
241	        if (mainThreadHandler == null) {
242	          mainThreadHandler = new Handler(Looper.getMainLooper());
243	          invalidateSelfRunnable = () -> {
244	            final Callback callback = getCallback();
245	            if (callback != null) {
246	              callback.invalidateDrawable(this);
247	            }
248	          };
249	        }
250	        mainThreadHandler.post(invalidateSelfRunnable);
251	      }
252	    } catch (InterruptedException e) {
253	      // Do nothing.
254	    } finally {
255	      setProgressDrawLock.release();
256	    }
257	  };
