418	   * Create a composition with {@link LottieCompositionFactory}
419	   *
420	   * @return True if the composition is different from the previously set composition, false otherwise.
421	   */
422	  public boolean setComposition(LottieComposition composition) {
423	    if (this.composition == composition) {
424	      return false;
425	    }
426	
427	    isDirty = true;
428	    clearComposition();
429	    this.composition = composition;
430	    buildCompositionLayer();
431	    animator.setComposition(composition);
432	    setProgress(animator.getAnimatedFraction());
433	
434	    // We copy the tasks to a new ArrayList so that if this method is called from multiple threads,
435	    // then there won't be two iterators iterating at the same time.
436	    List<LazyCompositionTask> tasks = new ArrayList<>(lazyCompositionTasks);
437	    for (LazyCompositionTask t : tasks) {
438	      // The task should never be null but it appears to happen in rare cases. Maybe it's an oem-specific or ART bug.
439	      // https://github.com/airbnb/lottie-android/issues/1702
440	      if (t != null) {
441	        t.run(composition);
442	      }
443	    }
444	    lazyCompositionTasks.clear();
445	
446	    composition.setPerformanceTrackingEnabled(performanceTrackingEnabled);
447	    computeRenderMode();
448	
449	    // Ensure that ImageView updates the drawable width/height so it can
450	    // properly calculate its drawable matrix.
451	    Callback callback = getCallback();
452	    if (callback instanceof ImageView) {
453	      ((ImageView) callback).setImageDrawable(null);
454	      ((ImageView) callback).setImageDrawable(this);
455	    }
456	
457	    return true;
458	  }
