700	  /**
701	   * Helper for the async execution path to potentially call setProgress
702	   * before drawing if the current progress has drifted sufficiently far
703	   * from the last set progress.
704	   *
705	   * @see AsyncUpdates
706	   * @see #setAsyncUpdates(AsyncUpdates)
707	   */
708	  private boolean shouldSetProgressBeforeDrawing() {
709	    LottieComposition composition = this.composition;
710	    if (composition == null) {
711	      return false;
712	    }
713	    float lastDrawnProgress = this.lastDrawnProgress;
714	    float currentProgress = animator.getAnimatedValueAbsolute();
715	    this.lastDrawnProgress = currentProgress;
716	
717	    float duration = composition.getDuration();
718	
719	    float deltaProgress = Math.abs(currentProgress - lastDrawnProgress);
720	    float deltaMs = deltaProgress * duration;
721	    return deltaMs >= MAX_DELTA_MS_ASYNC_SET_PROGRESS;
722	  }
