728	      return;
729	    }
730	    boolean asyncUpdatesEnabled = getAsyncUpdatesEnabled();
731	    try {
732	      if (asyncUpdatesEnabled) {
733	        setProgressDrawLock.acquire();
734	      }
735	      if (L.isTraceEnabled()) {
736	        L.beginSection("Drawable#draw");
737	      }
738	
739	      if (asyncUpdatesEnabled && shouldSetProgressBeforeDrawing()) {
740	        setProgress(animator.getAnimatedValueAbsolute());
741	      }
742	
743	      if (safeMode) {
744	        try {
745	          dispatchDraw(canvas, compositionLayer);
746	        } catch (Throwable e) {
747	          Logger.error("Lottie crashed in draw!", e);
748	        }
749	      } else {
750	        dispatchDraw(canvas, compositionLayer);
751	      }
752	
753	      isDirty = false;
754	    } catch (InterruptedException e) {
755	      // Do nothing.
756	    } finally {
757	      if (L.isTraceEnabled()) {
758	        L.endSection("Drawable#draw");
759	      }
760	      if (asyncUpdatesEnabled) {
761	        setProgressDrawLock.release();
762	        if (compositionLayer.getProgress() != animator.getAnimatedValueAbsolute()) {
763	          setProgressExecutor.execute(updateProgressRunnable);
764	        }
765	      }
766	    }
767	  }
