771	   */
772	  @RestrictTo(RestrictTo.Scope.LIBRARY_GROUP)
773	  public void draw(Canvas canvas, Matrix matrix) {
774	    CompositionLayer compositionLayer = this.compositionLayer;
775	    LottieComposition composition = this.composition;
776	    if (compositionLayer == null || composition == null) {
777	      return;
778	    }
779	    boolean asyncUpdatesEnabled = getAsyncUpdatesEnabled();
780	    try {
781	      if (asyncUpdatesEnabled) {
782	        setProgressDrawLock.acquire();
783	        if (shouldSetProgressBeforeDrawing()) {
784	          setProgress(animator.getAnimatedValueAbsolute());
785	        }
786	      }
787	
788	      if (safeMode) {
789	        try {
790	          draw(canvas, matrix, compositionLayer, alpha);
791	        } catch (Throwable e) {
792	          Logger.error("Lottie crashed in draw!", e);
793	        }
794	      } else {
795	        draw(canvas, matrix, compositionLayer, alpha);
796	      }
797	      isDirty = false;
798	    } catch (InterruptedException e) {
799	      // Do nothing.

800	    } finally {
801	      if (asyncUpdatesEnabled) {
802	        setProgressDrawLock.release();
803	        if (compositionLayer.getProgress() != animator.getAnimatedValueAbsolute()) {
804	          setProgressExecutor.execute(updateProgressRunnable);
805	        }
806	      }
807	    }
