810	  private void dispatchDraw(Canvas canvas, CompositionLayer compositionLayer) {
811	    if (useSoftwareRendering) {
812	      renderAndDrawAsBitmap(canvas, compositionLayer);
813	    } else {
814	      drawDirectlyToCanvas(canvas);
815	    }
816	  }
