818	  private void draw(Canvas canvas, Matrix matrix, CompositionLayer compositionLayer, int alpha) {
819	    if (useSoftwareRendering) {
820	      canvas.save();
821	      canvas.concat(matrix);
822	      renderAndDrawAsBitmap(canvas, compositionLayer);
823	      canvas.restore();
824	    } else {
825	      compositionLayer.draw(canvas, matrix, alpha, null);
826	    }
827	  }
