1440	   * returned {@link KeyPath} objects because they will be internally resolved to their content
1441	   * and won't trigger a tree walk of the animation contents when applied.
1442	   */
1443	  public List<KeyPath> resolveKeyPath(KeyPath keyPath) {
1444	    if (compositionLayer == null) {
1445	      Logger.warning("Cannot resolve KeyPath. Composition is not set yet.");
1446	      return Collections.emptyList();
1447	    }
