1453	  /**
1454	   * Add an property callback for the specified {@link KeyPath}. This {@link KeyPath} can resolve
1455	   * to multiple contents. In that case, the callback's value will apply to all of them.
1456	   * <p>
1457	   * Internally, this will check if the {@link KeyPath} has already been resolved with
1458	   * {@link #resolveKeyPath(KeyPath)} and will resolve it if it hasn't.
1459	   * <p>
1460	   * Set the callback to null to clear it.
1461	   */
1462	  public <T> void addValueCallback(
1463	      final KeyPath keyPath, final T property, @Nullable final LottieValueCallback<T> callback) {
1464	    if (compositionLayer == null) {
1465	      lazyCompositionTasks.add(c -> addValueCallback(keyPath, property, callback));
1466	      return;
1467	    }
1468	    boolean invalidate;
1469	    if (keyPath == KeyPath.COMPOSITION) {
1470	      compositionLayer.addValueCallback(property, callback);
1471	      invalidate = true;
1472	    } else if (keyPath.getResolvedElement() != null) {
1473	      keyPath.getResolvedElement().addValueCallback(property, callback);
1474	      invalidate = true;
1475	    } else {
1476	      List<KeyPath> elements = resolveKeyPath(keyPath);
1477	
1478	      for (KeyPath element : elements) {
1479	        //noinspection ConstantConditions
1480	        element.getResolvedElement().addValueCallback(property, callback);
1481	      }
1482	      invalidate = !elements.isEmpty();
1483	    }
1484	    if (invalidate) {
1485	      invalidateSelf();
1486	      if (property == LottieProperty.TIME_REMAP) {
1487	        // Time remapping values are read in setProgress. In order for the new value
1488	        // to apply, we have to re-set the progress with the current progress so that the
1489	        // time remapping can be reapplied.
1490	        setProgress(getProgress());
1491	      }
1492	    }
1493	  }
