1729	  /**
1730	   * Hardware accelerated render path.
1731	   */
1732	  private void drawDirectlyToCanvas(Canvas canvas) {
1733	    CompositionLayer compositionLayer = this.compositionLayer;
1734	    LottieComposition composition = this.composition;
1735	    if (compositionLayer == null || composition == null) {
1736	      return;
1737	    }
1738	
1739	    renderingMatrix.reset();
1740	    Rect bounds = getBounds();
1741	    if (!bounds.isEmpty()) {
1742	      // In fitXY mode, the scale doesn't take effect.
1743	      float scaleX = bounds.width() / (float) composition.getBounds().width();
1744	      float scaleY = bounds.height() / (float) composition.getBounds().height();
1745	
1746	      renderingMatrix.preTranslate(bounds.left, bounds.top);
1747	      renderingMatrix.preScale(scaleX, scaleY);
1748	    }
1749	    compositionLayer.draw(canvas, renderingMatrix, alpha, null);
1750	  }
