1752	  /**
1753	   * Software accelerated render path.
1754	   * <p>
1755	   * This draws the animation to an internally managed bitmap and then draws the bitmap to the original canvas.
1756	   *
1757	   * @see LottieAnimationView#setRenderMode(RenderMode)
1758	   */
1759	  private void renderAndDrawAsBitmap(Canvas originalCanvas, CompositionLayer compositionLayer) {
1760	    if (composition == null || compositionLayer == null) {
1761	      return;
1762	    }
1763	    ensureSoftwareRenderingObjectsInitialized();
1764	
1765	    //noinspection deprecation
1766	    originalCanvas.getMatrix(softwareRenderingOriginalCanvasMatrix);
1767	
1768	    // Get the canvas clip bounds and map it to the coordinate space of canvas with it's current transform.
1769	    originalCanvas.getClipBounds(canvasClipBounds);
1770	    convertRect(canvasClipBounds, canvasClipBoundsRectF);
1771	    softwareRenderingOriginalCanvasMatrix.mapRect(canvasClipBoundsRectF);
1772	    convertRect(canvasClipBoundsRectF, canvasClipBounds);
1773	
1774	    if (clipToCompositionBounds) {
1775	      // Start with the intrinsic bounds. This will later be unioned with the clip bounds to find the
1776	      // smallest possible render area.
1777	      softwareRenderingTransformedBounds.set(0f, 0f, getIntrinsicWidth(), getIntrinsicHeight());
1778	    } else {
1779	      // Calculate the full bounds of the animation.
1780	      compositionLayer.getBounds(softwareRenderingTransformedBounds, null, false);
1781	    }
1782	    // Transform the animation bounds to the bounds that they will render to on the canvas.
1783	    softwareRenderingOriginalCanvasMatrix.mapRect(softwareRenderingTransformedBounds);
1784	
1785	    // The bounds are usually intrinsicWidth x intrinsicHeight. If they are different, an external source is scaling this drawable.
1786	    // This is how ImageView.ScaleType.FIT_XY works.
1787	    Rect bounds = getBounds();
1788	    float scaleX = bounds.width() / (float) getIntrinsicWidth();
1789	    float scaleY = bounds.height() / (float) getIntrinsicHeight();
1790	    scaleRect(softwareRenderingTransformedBounds, scaleX, scaleY);
1791	
1792	    if (!ignoreCanvasClipBounds()) {
1793	      softwareRenderingTransformedBounds.intersect(canvasClipBounds.left, canvasClipBounds.top, canvasClipBounds.right, canvasClipBounds.bottom);
1794	    }
1795	
1796	    if (!isFiniteRect(softwareRenderingTransformedBounds)) {
1797	      Logger.warning("Skipping software rendering: transformed bounds contain non-finite values.");
1798	      return;
1799	    }
1800	
1801	    int renderWidth = (int) Math.ceil(softwareRenderingTransformedBounds.width());
1802	    int renderHeight = (int) Math.ceil(softwareRenderingTransformedBounds.height());
1803	
1804	    if (renderWidth <= 0 || renderHeight <= 0) {
1805	      Logger.warning("Skipping software rendering: transformed bounds have negative values.");
1806	      return;
1807	    }
1808	
1809	    long renderPixelCount = (long) renderWidth * (long) renderHeight;
1810	    if (renderPixelCount > MAX_SOFTWARE_BITMAP_PIXELS) {
1811	      Logger.warning("Skipping software rendering: bitmap request exceeds safe pixel count (" + renderPixelCount + ")");
1812	      return;
1813	    }
1814	
1815	    ensureSoftwareRenderingBitmap(renderWidth, renderHeight);
1816	
1817	    if (isDirty) {
1818	      softwareRenderingOriginalCanvasMatrix.getValues(softwareRenderingOriginalCanvasMatrixElements);
1819	      float preExistingScaleX = softwareRenderingOriginalCanvasMatrixElements[Matrix.MSCALE_X];
1820	      float preExistingScaleY = softwareRenderingOriginalCanvasMatrixElements[Matrix.MSCALE_Y];
1821	
1822	      renderingMatrix.set(softwareRenderingOriginalCanvasMatrix);
1823	      renderingMatrix.preScale(scaleX, scaleY);
1824	      // We want to render the smallest bitmap possible. If the animation doesn't start at the top left, we translate the canvas and shrink the
1825	      // bitmap to avoid allocating and copying the empty space on the left and top. renderWidth and renderHeight take this into account.
1826	      renderingMatrix.postTranslate(-softwareRenderingTransformedBounds.left, -softwareRenderingTransformedBounds.top);
1827	      renderingMatrix.postScale(1.0f / preExistingScaleX, 1.0f / preExistingScaleY);
1828	
1829	      softwareRenderingBitmap.eraseColor(0);
1830	      softwareRenderingCanvas.setMatrix(Utils.IDENTITY_MATRIX);
1831	      softwareRenderingCanvas.scale(preExistingScaleX, preExistingScaleY);
1832	      compositionLayer.draw(softwareRenderingCanvas, renderingMatrix, alpha, null);
1833	
1834	      // Calculate the dst bounds.
1835	      // We need to map the rendered coordinates back to the canvas's coordinates. To do so, we need to invert the transform
1836	      // of the original canvas.
1837	      // Take the bounds of the rendered animation and map them to the canvas's coordinates.
1838	      // This is similar to the src rect above but the src bound may have a left and top offset.
1839	      softwareRenderingOriginalCanvasMatrix.invert(softwareRenderingOriginalCanvasMatrixInverse);
1840	      softwareRenderingOriginalCanvasMatrixInverse.mapRect(softwareRenderingDstBoundsRectF, softwareRenderingTransformedBounds);
1841	      convertRect(softwareRenderingDstBoundsRectF, softwareRenderingDstBoundsRect);
1842	    }
1843	
1844	    softwareRenderingSrcBoundsRect.set(0, 0, renderWidth, renderHeight);
1845	    originalCanvas.drawBitmap(softwareRenderingBitmap, softwareRenderingSrcBoundsRect, softwareRenderingDstBoundsRect, softwareRenderingPaint);
1846	  }
