1848	  private void ensureSoftwareRenderingObjectsInitialized() {
1849	    if (softwareRenderingCanvas != null) {
1850	      return;
1851	    }
1852	    softwareRenderingCanvas = new Canvas();
1853	    softwareRenderingTransformedBounds = new RectF();
1854	    softwareRenderingOriginalCanvasMatrix = new Matrix();
1855	    softwareRenderingOriginalCanvasMatrixInverse = new Matrix();
1856	    canvasClipBounds = new Rect();
1857	    canvasClipBoundsRectF = new RectF();
1858	    softwareRenderingPaint = new LPaint();
1859	    softwareRenderingSrcBoundsRect = new Rect();
1860	    softwareRenderingDstBoundsRect = new Rect();
1861	    softwareRenderingDstBoundsRectF = new RectF();
1862	  }
1863	
1864	  private void ensureSoftwareRenderingBitmap(int renderWidth, int renderHeight) {
1865	    if (softwareRenderingBitmap == null ||
1866	        softwareRenderingBitmap.getWidth() < renderWidth ||
1867	        softwareRenderingBitmap.getHeight() < renderHeight) {
1868	      // The bitmap is larger. We need to create a new one.
1869	      softwareRenderingBitmap = Bitmap.createBitmap(renderWidth, renderHeight, Bitmap.Config.ARGB_8888);
1870	      softwareRenderingCanvas.setBitmap(softwareRenderingBitmap);
1871	      isDirty = true;
1872	    } else if (softwareRenderingBitmap.getWidth() > renderWidth || softwareRenderingBitmap.getHeight() > renderHeight) {
1873	      // The bitmap is smaller. Take subset of the original.
1874	      softwareRenderingBitmap = Bitmap.createBitmap(softwareRenderingBitmap, 0, 0, renderWidth, renderHeight);
1875	      softwareRenderingCanvas.setBitmap(softwareRenderingBitmap);
1876	      isDirty = true;
1877	    }
1878	  }
