1923	  /**
1924	   * When a View's parent has clipChildren set to false, it doesn't affect the clipBound
1925	   * of its child canvases so we should explicitly check for it and draw the full animation
1926	   * bounds instead.
1927	   */
1928	  private boolean ignoreCanvasClipBounds() {
1929	    Callback callback = getCallback();
1930	    if (!(callback instanceof View)) {
1931	      // If the callback isn't a view then respect the canvas's clip bounds.
1932	      return false;
1933	    }
1934	    ViewParent parent = ((View) callback).getParent();
1935	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2 && parent instanceof ViewGroup) {
1936	      return !((ViewGroup) parent).getClipChildren();
1937	    }
1938	    // Unlikely to ever happen. If the callback is a View, its parent should be a ViewGroup.
1939	    return false;
1940	  }

